INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Programmierparadigma immer an eine bestimmte Sprache gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Paradigmen sind unabhängig von Sprachen"}, {"text": "Ja", "correct": false, "because": "Sprachen unterstützen oft mehrere"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Programmierparadigmas?', 3, '[{"text": "Strukturierte Problemlösung", "correct": true, "because": "Definiert Programmieransatz"}, {"text": "Maximale Codezeilen", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Manuelle Optimierung", "correct": false, "because": "Paradigmen strukturieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmierparadigmen gibt es?', 5, '[{"text": "Objektorientiert", "correct": true, "because": "Nutzt Klassen und Objekte"}, {"text": "Funktional", "correct": true, "because": "Basiert auf mathematischen Funktionen"}, {"text": "Grafisch", "correct": false, "because": "Kein Standardparadigma"}, {"text": "Manuell", "correct": false, "because": "Kein Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objektorientierte Programmierung nutzt Vererbung. b) Funktionale Programmierung erlaubt Seiteneffekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) vermeidet Seiteneffekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Programmierparadigmas?', 4, '[{"text": "Projektanforderungen", "correct": false, "because": "Bestimmen Eignung"}, {"text": "Teamkompetenz", "correct": false, "because": "Beeinflusst Umsetzung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob objektorientierte Programmierung modularen Code fördert?', 2, '[{"text": "Ja", "correct": true, "because": "Klassen fördern Wiederverwendung"}, {"text": "Nein", "correct": false, "because": "Modularität zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Paradigma eignet sich für parallele Verarbeitung?', 3, '[{"text": "Funktional", "correct": true, "because": "Vermeidet Zustandsänderungen"}, {"text": "Imperativ", "correct": false, "because": "Zustandsabhängig"}, {"text": "Manuell", "correct": false, "because": "Kein Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet objektorientierte Programmierung?', 5, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Klassen und Vererbung"}, {"text": "Kapselung", "correct": true, "because": "Schützt Daten"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einheitlicher Code", "correct": false, "because": "Modularität zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Funktionale Programmierung nutzt reine Funktionen. b) Sie ist immer langsamer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Implementierung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Wahl eines Programmierparadigmas?', 4, '[{"text": "Problemanalyse", "correct": false, "because": "Bestimmt Eignung"}, {"text": "Sprachkenntnisse", "correct": false, "because": "Beeinflussen Umsetzung"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist objektorientierte Programmierung immer besser als funktionale?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Projekt"}, {"text": "Ja", "correct": false, "because": "Kein Paradigma universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprachen unterstützen mehrere Paradigmen?', 4, '[{"text": "Python", "correct": true, "because": "Objektorientiert und funktional"}, {"text": "JavaScript", "correct": true, "because": "Imperativ und funktional"}, {"text": "HTML", "correct": false, "because": "Keine Programmiersprache"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass imperative Programmierung veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Weiterhin in vielen Bereichen genutzt"}, {"text": "Ja", "correct": false, "because": "Nicht veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Paradigmas?', 3, '[{"text": "Projektanforderungen", "correct": true, "because": "Bestimmen Eignung"}, {"text": "Maximale Komplexität", "correct": false, "because": "Einfachheit wichtiger"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Deklarative Programmierung beschreibt das Was. b) Sie ist immer objektorientiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei funktionaler Programmierung?', 5, '[{"text": "Lernkurve", "correct": true, "because": "Neues Denkmodell"}, {"text": "Seiteneffektvermeidung", "correct": true, "because": "Komplex bei IO"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkproblem"}, {"text": "Einheitlicher Code", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wahl eines Paradigmas unwichtig?', 3, '[{"text": "Skalierbarkeit", "correct": false, "because": "Beeinflusst Architektur"}, {"text": "Wartbarkeit", "correct": false, "because": "Wichtig für Pflege"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Programmierfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob deklarative Programmierung das Wie beschreibt?', 2, '[{"text": "Nein", "correct": true, "because": "Beschreibt das Was"}, {"text": "Ja", "correct": false, "because": "Imperativ beschreibt Wie"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert objektorientierte Programmierung Wiederverwendbarkeit?', 3, '[{"text": "Ja", "correct": true, "because": "Klassen und Module"}, {"text": "Nein", "correct": false, "because": "Wiederverwendung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Programmierparadigma?', 4, '[{"text": "Entwicklung einer skalierbaren App", "correct": true, "because": "Paradigma beeinflusst Design"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Programmierfokus"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
